const day = { amanhã: 'mañana', segunda: 'lunes', terça: 'martes', quarta: 'miércoles', quinta: 'jueves', sexta: 'viernes' };
const list = (s, t) => s.split(/, | e /).map((x) => t(x)).join(', ').replace(/, ([^,]+)$/, ' y $1');

const patterns = [
  [/^(.+) \| AlquiVerde$/, (m, t, s) => (s(m[1]) ? `${s(m[1])} | Alquiverde` : null)],
  [/^(.+)\. Veja os itens, as opções de embalagem e os cuidados de uso\.$/, (m, t, s) => (s(m[1]) ? `${s(m[1])}. Mira los artículos, las opciones de empaque y los cuidados de uso.` : null)],
  [/^De R\$ ([\d.,]+) por R\$ ([\d.,]+) \((\d+)% de desconto\)$/, (m) => `Antes R$ ${m[1]}, ahora R$ ${m[2]} (${m[3]}% de descuento)`],
  [/^R\$ [\d.,]+$/, (m) => m[0]],
  [/^[\d.,]+ ?(?:g|mL|ml|cm|h|min)$/, (m) => m[0]],
  [/^(\d+) de (\d+) · faltam (\d+)$/, (m) => `${m[1]} de ${m[2]} · faltan ${m[3]}`],
  [/^(\d+) de (\d+) · caixa completa$/, (m) => `${m[1]} de ${m[2]} · caja completa`],
  [/^(\d+)\/(\d+) sabonetes(?: · (\d+) extras?)?$/, (m) => `${m[1]}/${m[2]} jabones${m[3] ? ` · ${m[3]} extra${m[3] > 1 ? 's' : ''}` : ''}`],
  [/^opcional · até (\d+)$/, (m) => `opcional · hasta ${m[1]}`],
  [/^\+ até (\d+) extras$/, (m) => `+ hasta ${m[1]} extras`],
  [/^Caixa de presente para (\d+) sabonetes$/, (m) => `Caja de regalo para ${m[1]} jabones`],
  [/^Faltam (\d+) sabonetes?$/, (m) => (m[1] > 1 ? `Faltan ${m[1]} jabones` : 'Falta 1 jabón')],
  [/^(\d+) itens, um por um\. (.+)$/, (m, t) => `${m[1]} artículo${m[1] > 1 ? 's' : ''}, uno por uno. ${t(m[2])}`],
  [/^(\d+) sabonetes · (\d+) g no total\. (.+)$/, (m, t) => `${m[1]} jabones · ${m[2]} g en total. ${t(m[3])}`],
  [/^(\d+) ×$/, (m) => m[0]],
  [/^(\d+) × (.+)$/, (m, t) => `${m[1]} × ${t(m[2])}`],
  [/^Caixa aberta do (.+)$/, (m, t) => `Caja abierta del ${t(m[1])}`],
  [/^Conhecer (.+)$/, (m, t, s) => (s(m[1]) ? `Conocer ${s(m[1])}` : null)],
  [/^(.+) em 3D\. Arraste ou use as setas para girar\.$/, (m, t) => `${t(m[1])} en 3D. Arrastra o usa las flechas para girar.`],
  [/^Pôr um sabonete de (.+)$/, (m, t) => `Añadir un jabón de ${t(m[1])}`],
  [/^Tirar um sabonete de (.+)$/, (m, t) => `Quitar un jabón de ${t(m[1])}`],
  [/^Sabonetes de (.+) na caixa$/, (m, t) => `Jabones de ${t(m[1])} en la caja`],
  [/^Combinação do (.+)$/, (m, t) => `Combinación del ${t(m[1])}`],
  [/^Vem no (.+)$/, (m, t) => `Viene en el ${list(m[1], t)}`],
  [/^Vem na combinação (.+)$/, (m, t) => `Viene en la combinación ${m[1].split(' e ').map(t).join(' y ')}`],
  [/^Sabonetes? [Vv]egeta(?:l|is) de (.+)$/, (m, t, s) => (s(m[1]) ? `${/^Sabonetes/.test(m[0]) ? 'Jabones vegetales' : 'Jabón vegetal'} de ${s(m[1])}` : null)],
  [/^Sabonete vegetal (.+) 90 g$/, (m, t, s) => (s(m[1]) ? `Jabón vegetal de ${s(m[1])} 90 g` : null)],
  [/^Óleo Essencial de (.+?)( 10 mL)?$/, (m, t, s) => (s(m[1]) ? `Aceite Esencial de ${s(m[1])}${m[2] || ''}` : null)],
  [/^Obrigada, (.+)!$/, (m) => `¡Gracias, ${m[1]}!`],
  [/^Pedido de proposta para (.+) presentes enviado\. A equipe responde no seu e-mail em até 1 dia útil\.$/, (m, t) => {
    const q = t(m[1].charAt(0).toUpperCase() + m[1].slice(1)).toLowerCase();
    return `Pedido de propuesta para ${q} regalos enviado. El equipo responde a tu correo en hasta 1 día hábil.`;
  }],
  [/^Peça nas próximas (.+) e receba hoje$/, (m) => `Pide en las próximas ${m[1]} y recíbelo hoy`],
  [/^Próxima entrega no mesmo dia: (\S+), pedidos até 12h$/, (m) => `Próxima entrega el mismo día: ${day[m[1]] || m[1]}, pedidos hasta las 12 h`],
  [/^Kit (\d+) de (\d+): (.+)$/, (m, t) => `Kit ${m[1]} de ${m[2]}: ${t(m[3])}`],
  [/^Kit Monte o seu · (\d+) sabonetes$/, (m) => `Kit Arma el tuyo · ${m[1]} jabones`],
  [/^\+ (.+)$/, (m, t) => `+ ${m[1].split(', ').map(t).join(', ')}`],
  [/^(.+?) \+ (\D.*)$/, (m, t) => `${t(m[1])} + ${m[2].split(', ').map(t).join(', ')}`],
  [/^(\d+) (\p{L}.*)$/u, (m, t, s) => (s(m[2]) ? `${m[1]} ${s(m[2])}` : null)],
  [/^(.+?): (.+?) Presente nos kits (.+)\.$/, (m, t) => `${t(m[1])}: ${t(m[2])} Va en los kits ${m[3].split(', ').map(t).join(', ')}.`],
  [/^([^:]+): (.+)$/, (m, t, s) => (s(m[1]) && s(m[2]) ? `${s(m[1])}: ${s(m[2])}` : null)],
];

export default { text: { ...NAMES, ...TEXT }, patterns };
